#include <stdint.h>

#define RCC_APB2ENR  (*(volatile uint32_t*)0x40021018)
#define GPIOC_CRH    (*(volatile uint32_t*)0x40011004)
#define GPIOC_BSRR   (*(volatile uint32_t*)0x40011010)   /* cơ sở + 0x10 */
#define GPIOC_BRR    (*(volatile uint32_t*)0x40011014)   /* cơ sở + 0x14 */
#define SET_BIT( reg, n) ((reg) |= (1U << (n)))

static void delay(volatile uint32_t n)
{
    while (n--) { }
}

int main(void)
{
    /* 1. Bật clock GPIOC: đặt bit 4 của RCC_APB2ENR */
SET_BIT(RCC_APB2ENR, 4);
GPIOC_CRH &=~ (0xFU << 20);
GPIOC_CRH |= (0x2U << 20);


    /* 2. Cấu hình PC13: xóa 4 bit ở vị trí 20 đến 23 của CRH,
          rồi đặt MODE = 10, CNF = 00 */


    for (;;)
    {
        /* 3. LED sáng */
GPIOC_BSRR = (1U<<29);
        delay(1000000);
        /* 4. LED tắt */
GPIOC_BSRR = (1U<<13);
        delay(1000000);
    }
}

